steps.script:
# Same position as exam mv10_creep_to_keep_heavy (without the profile
# line): Custodian Guard Beta with a constructed 36" BS 4+ [HEAVY] heavy
# bolter just north of area-medium-7 (a LIGHT area), its only target
# Custodian Guard Alpha (P2) in the open corridor south of it - every line
# between them crosses area-medium-7 (13.10) - and Delta (the same gun) in
# the open on the north edge with Custodian Guard Beta (P2) in sight.
var st = GameState.state
# No 2000-pt fixture fields a [HEAVY] weapon, so two Custodian Guard squads
# swap their guardian spears' ranged profile for a constructed heavy bolter
# (36", A3, BS 4+, S5, AP-1, D2, [HEAVY]; the melee profile is kept).
# granted_by makes every model carry it whatever the resolved loadout says
# (RulesEngine._get_model_weapon_ids); unique names, because a weapon id
# resolves by name across the board.
var hb = {"name": "Exam heavy bolter", "type": "Ranged", "range": "36", "attacks": "3", "ballistic_skill": "4", "strength": "5", "ap": "-1", "damage": "2", "special_rules": "heavy", "abilities": [{"id": "heavy"}], "granted_by": "exam"}
var hbd = hb.duplicate(true)
hbd["name"] = "Exam heavy bolter D"
var arm = {"U_CUSTODIAN_GUARD_B": hb, "U_CUSTODIAN_GUARD_D": hbd}
for uid in arm:
	var u = st.units[uid]
	var kept = []
	for w in u.meta.weapons:
		if str(w.get("type", "")).to_lower() != "ranged":
			kept.append(w)
	kept.append(arm[uid])
	u.meta.weapons = kept
# Beta just north of area-medium-7 (a LIGHT terrain area, x 1120-1360,
# y 360-520: an obscuring area, 13.10) with every base outside it; its only
# reachable target, Custodian Guard Alpha (P2), stands in the open corridor
# south of it (between the Center ruin and area-medium-35), so every line
# between them crosses area-medium-7. Delta in the open on the north edge,
# far from every terrain area, with a clear line to Custodian Guard Beta
# (P2) on the east-edge lane past area-large-2.
var place = {
	"U_CUSTODIAN_GUARD_B": [Vector2(1160, 320), Vector2(1226, 320), Vector2(1292, 320), Vector2(1193, 265), Vector2(1259, 265)],
	"U_CUSTODIAN_GUARD_D": [Vector2(1560, 220), Vector2(1626, 220), Vector2(1692, 220), Vector2(1593, 160), Vector2(1659, 160)],
	"U_CUSTODIAN_GUARD_A_P2": [Vector2(1160, 1330), Vector2(1226, 1330), Vector2(1160, 1395), Vector2(1226, 1395), Vector2(1193, 1460)],
	"U_CUSTODIAN_GUARD_B_P2": [Vector2(1640, 1150), Vector2(1704, 1150), Vector2(1640, 1214), Vector2(1704, 1214), Vector2(1672, 1278)],
}
for uid in place:
	var k = 0
	for m in st.units[uid].models:
		m.position = {"x": place[uid][k].x, "y": place[uid][k].y}
		k += 1
	if st.units[uid].has("flags"):
		st.units[uid].flags.erase("last_shot_idx")
		st.units[uid].flags.erase("shot_recently")
# Park everyone else, stacked per unit. Player 1 alternates between
# obj_home_1's ruin (area-large-14) and obj_nml_1's ruin (area-large-2), so
# both are already held; player 2 goes to the south-east corner, more than
# 42" from Beta and Delta.
var alt = 0
for uid in st.units:
	if place.has(uid):
		continue
	var u = st.units[uid]
	var q = 0
	var spot = alt % 2
	if int(u.get("owner", 0)) == 1:
		alt += 1
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		if int(u.get("owner", 0)) == 1:
			if spot == 0:
				m.position = {"x": 600.0 + 40.0 * float(q % 5), "y": 300.0}
			else:
				m.position = {"x": 1450.0 + 40.0 * float(q % 4), "y": 540.0}
		else:
			m.position = {"x": 1500.0 + 40.0 * float(q % 5), "y": 2300.0}
		q += 1
return TerrainManager.area_at(Vector2(1240.0, 440.0)).get("id", "")

# FIX_HEAVY_CREEP ships OFF: load the opt-in profile AFTER configure()
# (configure wipes profiles).
var f = FileAccess.open("res://tests/bench_profiles/heavy_creep_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
return prof.parameters.size()

# Engine-level check of the same suggestion: a Normal move carrying the
# 3" re-plan cap, no model further than 2.9" (straight line), every
# destination centre inside area-medium-7.
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
if str(d.get("type", "")) != "BEGIN_NORMAL_MOVE" or not is_equal_approx(float(d.get("_ai_move_cap_inches", 0.0)), 3.0):
	return false
var dests: Dictionary = d.get("_ai_model_destinations", {})
if dests.size() != 5:
	return false
var models: Array = AIDecisionMaker._get_alive_models_with_positions(GameState.state.units["U_CUSTODIAN_GUARD_B"])
if AIDecisionMaker._destinations_max_move_inches(models, dests) > 2.9:
	return false
for mid in dests:
	var p = Vector2(float(dests[mid][0]), float(dests[mid][1]))
	if str(TerrainManager.area_at(p).get("id", "")) != "area-medium-7":
		return false
return true

# SHIPPED-DEFAULT CHECK: clearing the profile leaves FIX_HEAVY_CREEP at 0 -
# T7-26's unchanged hold, no cap key, no creep wording.
AIDecisionMaker.clear_player_profile(1)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
return str(d.get("type", "")) == "REMAIN_STATIONARY" and str(d.get("_ai_description", "")).begins_with("Custodian Guard Beta holds for Heavy weapon bonus") and not d.has("_ai_move_cap_inches") and not str(d.get("_ai_description", "")).contains("to keep its [HEAVY]")

# Reload the profile: the creep returns.
var f = FileAccess.open("res://tests/bench_profiles/heavy_creep_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
return str(d.get("type", "")) == "BEGIN_NORMAL_MOVE" and str(d.get("_ai_description", "")).contains("to keep its [HEAVY] +1 to hit")

# ENGINE truth after the accepted move: a Normal move (not Remain
# Stationary, not an Advance) whose longest model move is 1-3" by the
# engine's own count, [HEAVY] still applies (24.16), every centre in a
# terrain area (13.08), and Alpha is an eligible target of the heavy bolter.
var u = GameState.state.units["U_CUSTODIAN_GUARD_B"]
var f = u.get("flags", {})
if not bool(f.get("moved", false)) or bool(f.get("remained_stationary", false)) or bool(f.get("advanced", false)):
	return -1.0
var mx = float(f.get("moved_max_inches", 99.0))
if mx < 1.0 or mx > 3.0:
	return -2.0
if not ModifierStack.heavy_applies_11e(u, GameState.state):
	return -3.0
if not TerrainManager.unit_has_cover_11e(u, {}):
	return -4.0
var snap = GameState.create_snapshot()
snap.units.U_CUSTODIAN_GUARD_B.flags["in_engagement"] = false
var elig = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, false)
if not elig.has("U_CUSTODIAN_GUARD_A_P2") or not ("exam_heavy_bolter_ranged" in elig.U_CUSTODIAN_GUARD_A_P2.get("weapons_in_range", [])):
	return -5.0
return mx

# The guard: Delta (same gun, its target already in sight, no terrain within
# reach) still holds for its Heavy bonus - no move of 3" or less buys it enough.
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_D")
return str(d.get("type", "")) == "REMAIN_STATIONARY" and str(d.get("_ai_description", "")).begins_with("Custodian Guard Delta holds for Heavy weapon bonus") and not d.has("_ai_move_cap_inches")
